<?php $title='Login';include 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=db()->prepare('SELECT * FROM users WHERE email=? AND status=1');$st->execute([trim($_POST['email'])]);$u=$st->fetch();if($u && password_verify($_POST['password'],$u['password_hash'])){$_SESSION['user']=$u;header('Location: '.($u['role']==='admin'?'admin/index.php':'customer/dashboard.php'));exit;}flash('danger','Invalid email or password.');} ?><section class="section"><div class="container" style="max-width:500px"><h1>Login</h1><?php show_flash();?><form method="post" class="card p-4 mt-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="email" name="email" class="form-control mb-3" placeholder="Email" required><input type="password" name="password" class="form-control mb-3" placeholder="Password" required><button class="btn btn-gold">Login</button><a href="register.php" class="gold mt-3">Create customer account</a></form></div></section><?php include 'includes/footer.php';?>
